const vm = require("node:vm");
const src = fs.readFileSync(process.argv[2], "utf8");

function el(id) {
  return {
    id, value: "", textContent: "", className: "", dataset: {}, children: [], listeners: {},
    addEventListener(t, fn) { (this.listeners[t] ||= []).push(fn); },
    appendChild(c) { this.children.push(c); },
    click() { (this.listeners.click || []).forEach(fn => fn({ target: this })); },
  };
}

function makeEnv(backing) {
  const elements = {};
  for (const id of ["filter", "tasks", "title", "add", "clear-completed"]) elements[id] = el(id);
  elements.filter.value = "all";
  const localStorage = {
    getItem: k => (k in backing ? backing[k] : null),
    setItem: (k, v) => { backing[k] = String(v); },
  };
  const document = {
    ready: null,
    addEventListener(t, fn) { if (t === "DOMContentLoaded") this.ready = fn; },
    getElementById: id => elements[id],
    createElement: () => el("li"),
  };
  const ctx = { document, localStorage, console, JSON };
  vm.createContext(ctx);
  vm.runInContext(src, ctx);
  document.ready();
  return { elements };
}

// Rendered titles are read from the list element's children.
const titles = elements => elements.tasks.children.map(c => c.textContent);
const addTask = (elements, title) => { elements.title.value = title; elements.add.click(); };
const completeTask = (elements, title) => {
  const item = elements.tasks.children.find(c => c.textContent === title);
  elements.tasks.listeners.click[0]({ target: item });
};

let failures = 0;
function check(label, actual, expected) {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (!ok) failures++;
  console.log(`${ok ? "PASS" : "FAIL"} ${label}: ${JSON.stringify(actual)}${ok ? "" : " expected " + JSON.stringify(expected)}`);
}

// Example 1: two completed and one open leaves only the open task, and it survives a reload.
const store1 = {};
