addTask(env.elements, "review");
addTask(env.elements, "plan");
completeTask(env.elements, "write");
completeTask(env.elements, "review");
env.elements["clear-completed"].click();
check("ex1 list after clear", titles(env.elements), ["plan"]);
env = makeEnv(store1);
check("ex1 list after reload", titles(env.elements), ["plan"]);

// Example 2: no completed tasks means nothing changes.
