env = makeEnv(store2);
addTask(env.elements, "write");
addTask(env.elements, "review");
const storedBefore = store2.tasks;
env.elements["clear-completed"].click();
check("ex2 list unchanged", titles(env.elements), ["write", "review"]);
check("ex2 stored unchanged", store2.tasks === storedBefore || store2.tasks === JSON.stringify(JSON.parse(storedBefore)), true);

// The filter selection is not changed by clearing.
const store3 = { filter: "done" };
env = makeEnv(store3);
env.elements["clear-completed"].click();
check("filter kept after clear", store3.filter, "done");

console.log(failures === 0 ? "ALL E2E CHECKS PASSED" : `${failures} E2E CHECK(S) FAILED`);
process.exit(failures === 0 ? 0 : 1);
